package com.customrpg.vfx;

import com.customrpg.talents.EarthSkill;
import com.customrpg.vfx.VfxMath.V;
import com.customrpg.vfx.VfxRuntime.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class EarthVfxTest {
    @Test void eightIndependentAnimationsHaveDifferentSilhouettesMotionAndSignaturesAndStayWithinBudgets(){var types=new HashSet<Class<?>>();for(var s:EarthSkill.values())for(V dir:List.of(V.FORWARD,new V(1,0,0),V.UP,new V(0,-1,0))){var scene=new VfxRuntimeTest.Scene();var r=new VfxRuntime(scene,Limits.defaults(),()->0);var effect=EarthVfx.preview(s.id,42);types.add(effect.getClass());assertEquals(s.id,VfxEffects.resolve(s.id));assertEquals(s.id,VfxEffects.resolve(s.name().toLowerCase(Locale.ROOT)));assertNotNull(r.play(s.id,new Pose(VfxRuntimeTest.OWNER,VfxRuntimeTest.WORLD,V.ZERO,dir,1,null),Mode.PREVIEW,effect,42,false,0,10));for(int i=0;i<=effect.duration();i++){r.tick();assertEquals(0,r.stats().rejectedSamples(),s.id+" tick "+i);assertTrue(r.stats().sampled()<=effect.sampleBudget());}assertFalse(scene.particles.isEmpty());assertEquals(0,scene.failures);assertEquals(0,r.stats().active());}assertEquals(8,types.size());assertEquals(8,EarthVfx.designs().stream().map(VfxEffects.Dna::silhouette).distinct().count());assertEquals(8,EarthVfx.designs().stream().map(VfxEffects.Dna::motion).distinct().count());assertEquals(8,EarthVfx.designs().stream().map(VfxEffects.Dna::signature).distinct().count());}
    @Test void titanAtLowQualityRetainsWarningAndAllFourRaisedMonuments(){var scene=new VfxRuntimeTest.Scene();scene.audience=List.of(new Viewer(VfxRuntimeTest.VIEWER,VfxRuntimeTest.WORLD,V.ZERO,Quality.LOW));var r=new VfxRuntime(scene,Limits.defaults(),()->0);r.play("earth_titan",VfxRuntimeTest.pose(),Mode.PREVIEW,new EarthVfx.Titan(new EarthVfx.Anchor()),42,false,0,100);for(int i=0;i<24;i++)r.tick();scene.particles.clear();r.tick();assertTrue(scene.particles.stream().anyMatch(p->p.at().y()<.1&&p.at().length()>6));for(V axis:List.of(new V(1,0,0),new V(-1,0,0),V.FORWARD,new V(0,0,-1)))assertTrue(scene.particles.stream().anyMatch(p->p.at().y()>3&&p.at().dot(axis)>5));}
    @Test void previewDemonstratesOathTransferAndReprisalWithoutCombat(){for(String id:List.of("earth_oath","earth_reprisal","earth_guard")){var scene=new VfxRuntimeTest.Scene();var r=new VfxRuntime(scene,Limits.defaults(),()->0);r.play(id,VfxRuntimeTest.pose(),Mode.PREVIEW,EarthVfx.preview(id,42),42,false,0,10);for(int i=0;i<55;i++)r.tick();assertFalse(scene.particles.isEmpty());if(id.equals("earth_reprisal"))assertTrue(scene.sounds.contains("block.deepslate.break"));}}
    @Test void movingAndRotatingAegisUsesDynamicAnchorWithoutAccumulatedTranslation(){var scene=new VfxRuntimeTest.Scene();var r=new VfxRuntime(scene,Limits.defaults(),()->0);var a=new EarthVfx.Anchor();var id=r.play("earth_guard",VfxRuntimeTest.pose(),Mode.COMBAT,new EarthVfx.Aegis(a,false),1,false,0,60);for(int i=0;i<10;i++)r.tick();a.offset=new V(5,0,0);a.yaw=Math.PI;scene.particles.clear();r.tick();r.tick();assertTrue(scene.particles.stream().allMatch(p->p.at().x()>3&&p.at().x()<7&&p.at().z()<0));r.cancelInstance(id);assertEquals(0,r.stats().active());}
    @Test void sixtyFourEarthAnimationsRespectGlobalLimitsAndEndCleanly(){var scene=new VfxRuntimeTest.Scene();var r=new VfxRuntime(scene,Limits.defaults(),()->0);for(int i=0;i<64;i++){var s=EarthSkill.values()[i%8];assertNotNull(r.play(s.id,new Pose(UUID.randomUUID(),VfxRuntimeTest.WORLD,V.ZERO,V.FORWARD,0,null),Mode.COMBAT,EarthVfx.preview(s.id,i),i,false,0,s==EarthSkill.TITAN?100:40));}for(int t=0;t<202;t++){r.tick();assertTrue(r.stats().sampled()<=8192);assertTrue(r.stats().sent()<=4000);assertTrue(r.stats().deliveryChecks()<=16000);scene.particles.clear();}assertEquals(0,r.stats().active());}
}
